async fn extract_with_xberg(path: &str) -> Result<String, String> {
    let extraction_config = ExtractionConfig::default();
    let input = ExtractInput::from_uri(path);
    match xberg::extract(input, &extraction_config).await {
        Ok(extracted) => Ok(extracted.results[0].content.clone()),
        Err(e) => Err(format!("Failed to extract data: {e}")),
    }
}